import { readFileSync } from 'node:fs'
import { Chess } from 'chess.js'
import { describe, expect, it } from 'vitest'
import { ChessGame, parseUci } from '../src/logic/game'

/**
 * Differential test: the Android app's Kotlin rules engine (independent code) played random games and recorded, for every
 * position, the sorted legal-move set (as a hash), the SAN of the move played, whether it gave check and the game result
 * after it. The web stack (chess.js + our game layer) must reproduce all of it exactly.
 * Generated by tools/CorpusExport.kt.
 */
interface Corpus {
  starts: string[]
  games: Array<{ s: number; m: string; san: string; h: string; c: string; r: string }>
}
const corpus = JSON.parse(readFileSync(new URL('./fixtures/kotlin-corpus.json', import.meta.url), 'utf8')) as Corpus

function fnv(text: string): string {
  let h = 0x811c9dc5
  for (const b of new TextEncoder().encode(text)) {
    h ^= b
    h = Math.imul(h, 0x01000193) >>> 0
  }
  return h.toString(16).padStart(8, '0')
}
const legalHash = (fen: string): string =>
  fnv(new Chess(fen).moves({ verbose: true }).map((m) => m.lan).sort().join(','))

describe('web rules vs the Kotlin engine (random playouts)', () => {
  it('has a meaningful corpus', () => {
    expect(corpus.games.length).toBeGreaterThanOrEqual(100)
    expect(corpus.games.reduce((n, g) => n + (g.m ? g.m.split(' ').length : 0), 0)).toBeGreaterThan(10_000)
  })

  it('agrees on legal moves, SAN, check and results at every ply', { timeout: 600_000 }, () => {
    let plies = 0
    for (const [index, g] of corpus.games.entries()) {
      const moves = g.m ? g.m.split(' ') : []
      const sans = g.san ? g.san.split(' ') : []
      const hashes = g.h.split(' ')
      const results = g.r ? g.r.split(' ') : []
      let game = ChessGame.new(corpus.starts[g.s])
      expect(legalHash(game.fen), `game ${index} start`).toBe(hashes[0])
      moves.forEach((text, i) => {
        const move = parseUci(text)!
        game = game.play(move)
        plies++
        const where = `game ${index} ply ${i + 1} (${text}) fen ${game.fen}`
        expect(game.records[i].san, `SAN ${where}`).toBe(sans[i])
        expect(legalHash(game.fen), `legal moves ${where}`).toBe(hashes[i + 1])
        expect(game.isCheck ? '1' : '0', `check ${where}`).toBe(g.c[i])
        expect(game.result?.termination ?? '-', `result ${where}`).toBe(results[i])
      })
    }
    expect(plies).toBeGreaterThan(10_000)
  })
})
